const sim = { time: 0, speed: state.playing ? 1 : 0, fade: 1, fadeTarget: 1, pending: false, refresh: 3, sys: null, mode: null, winter: 0, snow: 0, tIn: SCEN.cool.inA, ready: false, homeLock: true };
const fmt = v => `${v < 0 ? '\u2212' : ''}${Math.abs(v).toFixed(1)} \u00b0C`;
const setText = (n, s) => { if (n.textContent !== s) n.textContent = s; };
const ui = { state: $('#stState'), tIn: $('#tIn'), tOut: $('#tOut'), tSup: $('#tSup'), tExh: $('#tExh'), abs: $('#stAbs'), rel: $('#stRel') };
const activeSys = () => systems[sim.sys || state.system];

// ---------- camera + controls
const controls = new OrbitControls(camera, canvas);
Object.assign(controls, { enableDamping: true, dampingFactor: 0.08, rotateSpeed: 0.65, zoomSpeed: 0.8, panSpeed: 0.7, screenSpacePanning: true, minDistance: 0.45, maxDistance: 24, minPolarAngle: 0.35, maxPolarAngle: 1.62, minAzimuthAngle: -1.15, maxAzimuthAngle: 1.15 });
controls.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.PAN };
controls.touches = { ONE: THREE.TOUCH.ROTATE, TWO: THREE.TOUCH.DOLLY_PAN };
const homeView = () => {
  const a = camera.aspect, target = V(0.3, 1.25, -0.6), dist = a >= 1.5 ? 9.2 : clamp(8.6 / (0.5735 * a), 9.2, 22);
  return [target.clone().add(V(0.02, 0.1, 1).normalize().multiplyScalar(dist)), target];
};
const fly = { on: false, t: 0, dur: 1, p0: V(), t0: V(), p1: V(), t1: V() };
function flyTo(pos, target, dur = 1.5) {
  if (reduceMotion.matches || dur <= 0) { fly.on = false; camera.position.copy(pos); controls.target.copy(target); controls.update(); return; }
  Object.assign(fly, { on: true, t: 0, dur }); fly.p0.copy(camera.position); fly.t0.copy(controls.target); fly.p1.copy(pos); fly.t1.copy(target);
}
function flyHome(dur = 1.4) { const [p, t] = homeView(); sim.homeLock = true; flyTo(p, t, dur); }
controls.addEventListener('start', () => { fly.on = false; sim.homeLock = false; });
function zoomBy(f) {
  const off = camera.position.clone().sub(controls.target), len = off.length(), nl = clamp(len * f, controls.minDistance, controls.maxDistance);
  sim.homeLock = false; flyTo(controls.target.clone().add(off.multiplyScalar(nl / len)), controls.target.clone(), 0.35);
}
const TB = { min: V(-3.5, -0.2, -2.5), max: V(4.0, 3.0, 1.0) }, tclamp = V();
function clampTarget() {
  tclamp.copy(controls.target).clamp(TB.min, TB.max);
  if (!tclamp.equals(controls.target)) { const d = tclamp.sub(controls.target); controls.target.add(d); camera.position.add(d); }
}

// ---------- post-processing (falls back to direct rendering)
let composer = null;
try {
  const rt = new THREE.WebGLRenderTarget(4, 4, { type: THREE.HalfFloatType, samples: small() ? 0 : 4 });
  composer = new EffectComposer(renderer, rt);
  composer.addPass(new RenderPass(scene, camera));
  composer.addPass(new UnrealBloomPass(new THREE.Vector2(256, 256), 0.42, 0.55, 0.92));
  composer.addPass(new OutputPass());

